-- Đối tác có nhiều người liên hệ, một người là liên hệ chính (nhận bộ giấy tờ). Thay ba cột contact_* của ship_owner.
CREATE TABLE "ship_owner_contact" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "ship_owner_id" INTEGER NOT NULL REFERENCES "ship_owner" ("id") ON DELETE CASCADE,
  "name" varchar(150) NOT NULL,
  "position" varchar(100),
  "phone" varchar(30),
  "email" varchar(150),
  "is_primary" SMALLINT DEFAULT 0 NOT NULL CHECK ("is_primary" IN (0, 1)),
  "sort_order" INTEGER DEFAULT 0 NOT NULL,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE INDEX "ship_owner_contact_owner" ON "ship_owner_contact" ("ship_owner_id");
-- Mỗi đối tác tối đa một liên hệ chính.
CREATE UNIQUE INDEX "ship_owner_contact_primary" ON "ship_owner_contact" ("ship_owner_id") WHERE "is_primary" = 1;

INSERT INTO "ship_owner_contact" ("ship_owner_id", "name", "phone", "email", "is_primary")
SELECT "id", "contact_person", "contact_phone", "contact_email", 1
FROM "ship_owner"
WHERE "contact_person" IS NOT NULL AND btrim("contact_person") <> '';

ALTER TABLE "ship_owner"
  DROP COLUMN "contact_person",
  DROP COLUMN "contact_phone",
  DROP COLUMN "contact_email";
